sys_script_include.script:
var fieldMappingUtils = Class.create();
fieldMappingUtils.prototype = {
    initialize: function() {},

    tempRetrive: function(current) {
        //delete previous
        this.deletePrevious(current);

        //extract new fields
        var html = current.getValue('html_template');
        var fields = this.extractFieldTokens(html);
        var subtemp = this.extractSubTempTokens(html);

        //create mapping
        this.createFieldMappings(current, fields, 'template');
        this.createSubTemplates(current, subtemp);
    },

    subtempRetrive: function(current) {
        //delete previous
        this.deletePreviousSubtempFields(current);

        //extract new fields
        var html = current.getValue('html_template');
        var fields = this.extractFieldTokens(html);

        //create mapping
        this.createFieldMappings(current, fields, 'sub_template');
    },

    deletePreviousSubtempFields: function(current) {
        var grfield = new GlideRecord('x_2162040_documate_field_mapping');
        grfield.addQuery('mapping_context', 'sub_template');
        grfield.addQuery('sub_template', current.getUniqueValue());
        grfield.query();
        grfield.deleteMultiple();
    },

    deletePrevious: function(current) {
        var grfield = new GlideRecord('x_2162040_documate_field_mapping');
        grfield.addQuery('mapping_context', 'template');
        grfield.addQuery('template', current.getUniqueValue());
        grfield.query();
        grfield.deleteMultiple();


        var grSubtemp = new GlideRecord('x_2162040_documate_sub_template');
        grSubtemp.addQuery('template', current.getUniqueValue());
        grSubtemp.query();
        while (grSubtemp.next()) {
            this.deletePreviousSubtempFields(grSubtemp);
            grSubtemp.deleteRecord();
        }

		// var grEmail = new GlideRecord('x_2162040_documate_email');
		// grEmail.addQuery('template',current.getUniqueValue());
		// grEmail.query();
		// while(grEmail.next()){
		// 	this.deleteEmailMappings(grEmail);
		// 	grEmail.deleteRecord();
		// }
    },

    createFieldMappings: function(template, fields, context) {
        var templateSysId = template.getUniqueValue();
        var tempTable = template.getValue('table');

        for (var i = 0; i < fields.length; i++) {
            var token = fields[i];

            var fm = new GlideRecord('x_2162040_documate_field_mapping');
            fm.initialize();

            fm.setValue('name', token);
            fm.setValue('table', tempTable);
            fm.setValue('mapping_context', context);
            if (context == 'sub_template') {
                fm.setValue('sub_template', templateSysId);
				fm.setValue('template',template.getValue('template'));
            } else if (context == 'email_template') {
                fm.setValue('email_template', templateSysId);
				fm.setValue('template',template.getValue('template'));
            } else {
                fm.setValue('template', templateSysId);
            }

            fm.insert();
        }

        gs.info('Created field mappings count: ' + fields.length);
    },

    createSubTemplates: function(template, subtemps) {
        var templateSysId = template.getUniqueValue();

        for (var i = 0; i < subtemps.length; i++) {
            var sectionName = subtemps[i];

            var st = new GlideRecord('x_2162040_documate_sub_template');
            st.initialize();

            st.setValue('template', templateSysId);
            st.setValue('template_reference_field', sectionName);
            st.setValue('empty_message', "No Data");

            st.insert();
        }
    },

    emailRetrive: function(template) {
        this.deleteEmailMappings(template);

        var text = '';
        text += template.getValue('mail_subject') || '';
        text += '\n';
        text += template.getValue('mail_body') || '';

        var fields = this.extractFieldTokens(text);
        this.createFieldMappings(template, fields, 'email_template');

        gs.info('DocuMate: Created email field mappings count: ' + fields.length);
    },

    deleteEmailMappings: function(current) {
        var fm = new GlideRecord('x_2162040_documate_field_mapping');
        fm.addQuery('mapping_context', 'email_template');
        fm.addQuery('email_template', current.getUniqueValue());
        fm.query();

        fm.deleteMultiple();
    },

    extractFieldTokens: function(text) {
        var tokens = [];
        var found = {};

        if (!text)
            return tokens;

        //  * ${short_description}

        var regex = /(^|[^\$])\$\{([^}]+)\}/g;
        var match;

        while ((match = regex.exec(text)) !== null) {
            var token = match[2].trim();

            if (!found[token]) {
                found[token] = true;
                tokens.push(token);
            }
        }

        return tokens;
    },

    extractSubTempTokens: function(text) {
        var sections = [];
        var found = {};

        if (!text)
            return sections;

        //  * $${captured_updates}

        var regex = /\$\$\{([^}]+)\}/g;
        var match;

        while ((match = regex.exec(text)) !== null) {
            var sectionName = match[1].trim();

            if (!found[sectionName]) {
                found[sectionName] = true;
                sections.push(sectionName);
            }
        }

        return sections;
    },

    type: 'fieldMappingUtils'
};
